    <div class="item">
      <div class="photo"></div>
      <div class="info">
        <span class="name">تفاحة</span>
        <div class="stepper">
          <button class="dec">-</button>
          <input type="number" value="1" min="0" data-price="5" class="qty">
          <button class="inc">+</button>
        </div>
        <span class="price">5.00 AED</span>
      </div>
    </div>
    <!-- Item 2 -->
    <div class="item">
      <div class="photo"></div>
      <div class="info">
        <span class="name">حليب</span>
        <div class="stepper">
          <button class="dec">-</button>
          <input type="number" value="2" min="0" data-price="3" class="qty">
          <button class="inc">+</button>
        </div>
        <span class="price">6.00 AED</span>
      </div>
    </div>
    <!-- Item 3 -->
    <div class="item">
      <div class="photo"></div>
      <div class="info">
        <span class="name">خبز</span>
        <div class="stepper">
          <button class="dec">-</button>
          <input type="number" value="1" min="0" data-price="2" class="qty">
          <button class="inc">+</button>
        </div>
        <span class="price">2.00 AED</span>
      </div>
    </div>
  </section>
  <section class="promo">
    <input type="text" placeholder="رمز الخصم">
    <button>تطبيق</button>
  </section>
  <section class="summary">
    <div class="row">
      <span>المجموع الفرعي</span>
      <span id="subtotal">13.00 AED</span>
    </div>
    <div class="row">
      <span>ال شحن</span>
      <span>10.00 AED</span>
    </div>
    <div class="row">
      <span>ضريبة القيمة المضافة (5%)</span>
      <span id="vat">0.65 AED</span>
    </div>
    <div class="row total">
      <span>الإجمالي</span>
      <span id="total">23.65 AED</span>
    </div>
  </section>
  <button class="place-order">إتمام الطلب</button>
</div>
<script>
  // Update prices
  document.querySelectorAll('.stepper').forEach(function(stepper){
    const dec = stepper.querySelector('.dec');
    const inc = stepper.querySelector('.inc');
    const input = stepper.querySelector('.qty');
    const priceEl = stepper.closest('.item').querySelector('.price');
    const unitPrice = parseFloat(input.dataset.price);
    function update(){
      const qty = parseInt(input.value) || 0;
      const total = (qty * unitPrice).toFixed(2);
      priceEl.textContent = total + ' AED';
      updateSummary();
    }
    dec.addEventListener('click', function(){
      if(parseInt(input.value) > 0){
        input.value = parseInt(input.value) - 1;
        update();
      }
    });
    inc.addEventListener('click', function(){
      input.value = parseInt(input.value) + 1;
      update();
    });
    input.addEventListener('change', update);
  });
  function updateSummary(){
    let subtotal = 0;
    document.querySelectorAll('.item').forEach(function(item){
      const priceText = item.querySelector('.price').textContent;
      const price = parseFloat(priceText);
      subtotal += price;
    });
    const delivery = 10;
    const vat = subtotal * 0.05;
    const total = subtotal + delivery + vat;
    document.getElementById('subtotal').textContent = subtotal.toFixed(2) + ' AED';
    document.getElementById('vat').textContent = vat.toFixed(2) + ' AED';
    document.getElementById('total').textContent = total.toFixed(2) + ' AED';
  }
  // initial update
  updateSummary();
</script>
